mapper.select:
SELECT 
FROM aid_media_task_anomaly a
JOIN aid_media_task t ON t.id=a.task_id
LEFT JOIN sys_user u ON u.user_id=t.user_id
LEFT JOIN aid_canvas_task_binding b ON b.task_id=t.id

    AND a.task_id=#{taskId}
    AND t.user_id=#{userId}
    AND t.media_type=#{mediaType}
    AND a.anomaly_type=#{anomalyType}

        AND a.status=#{anomalyStatus}
        AND a.status IN ('PENDING','WAITING','COMPENSATION_PENDING')

    AND a.first_detected_time >= #{detectedStartTime}
    AND a.first_detected_time <= #{detectedEndTime}

ORDER BY a.last_detected_time DESC,a.id DESC
